// Generated by npm run build:seed from the owner-provided manual criteria.
var FMS_MANUAL_SOURCE = "# FMS Quick Screen - treści z podręcznika do aplikacji i raportu\n\n## Cel pliku\n\nTen plik jest źródłem tekstów dla aplikacji i raportu. Zawiera kryteria,\nwarunki wykonania, nazwy stron oraz znaczenie wyników wyciągnięte z\npodręcznika FMS Quick Screen Manual V2.pdf.\n\nTeksty po polsku są wiernym tłumaczeniem treści kryteriów z podręcznika.\nNie dodawaj do nich diagnozy, interpretacji klinicznej ani rekomendacji\ntreningowej. Oryginalny PDF pozostaje źródłem nadrzędnym.\n\nNie kopiuj do aplikacji całego podręcznika, długich instrukcji słownych,\nlogo ani układu FMS. Użyj poniższych krótkich, źródłowych fragmentów oraz\npodaj odwołanie do strony podręcznika.\n\n## Tekst wspólny do raportu: punktacja\n\n### Skala ruchowa 0-3\n\n| Wynik | Tekst do raportu | Źródło |\n|---|---|---|\n| 3 | Osoba wykonuje wzorzec ruchu dokładnie zgodnie z instrukcją i spełnia wszystkie zamierzone kryteria. | Manual, strona 7 |\n| 2 | Ruch jest wykonany, ale występuje zauważalna kompensacja. | Manual, strona 7 |\n| 1 | Osoba nie osiąga wymaganej pozycji albo nie wykonuje ruchu zgodnie z instrukcją; występuje istotna kompensacja. | Manual, strona 7 |\n| 0 | Ból jest obecny w dowolnym momencie ruchu, niezależnie od jakości wykonania. | Manual, strona 7 |\n\n### Wspólne reguły\n\n- Każdy test ruchowy można wykonać maksymalnie trzy razy.\n- Zapisuje się najlepsze wykonanie z maksymalnie trzech prób.\n- Jeżeli w pierwszej próbie uzyskano 3, dalsze próby nie są potrzebne.\n- Jeżeli wystąpi ból, wynik tego wzorca wynosi 0.\n- Jeżeli ocena wyższego wyniku jest niepewna, wybiera się wynik niższy.\n- Dla testów lewa/prawa wynik końcowy jest niższym wynikiem surowym z obu\n  stron.\n- Total Screen Score jest sumą wyników końcowych testów liczbowych.\n\nŹródło: Manual, strony 7-8 i 28; Scoresheet, opis Raw Score / Final Score.\n\n### Testy clearing\n\n| Odpowiedź | Tekst do raportu |\n|---|---|\n| Positive / Ból | W teście pojawił się ból. |\n| Negative / Brak bólu | W teście nie pojawił się ból. |\n\nJeżeli clearing test jest przypisany do wzorca ruchowego, odpowiedź Positive\nustawia wynik powiązanego wzorca na 0. Źródło: Manual, strona 8.\n\n## 1. Cervical Flexion\n\n**Kod:** cervical_flexion  \n**Źródło:** Manual, strona 9.\n\n### Tekst do raportu\n\nTest ocenia, czy szyja może wykonać zgięcie do wymaganego zakresu oraz czy\nruch jest wolny od bólu.\n\n### Pozycja i wykonanie\n\n- Osoba stoi prosto, ze stopami razem i rękami wzdłuż tułowia.\n- Usta pozostają zamknięte.\n- Dwa palce są ustawione pionowo jeden na drugim na górze mostka.\n- Broda jest powoli opuszczana w kierunku palców.\n- Dolna pozycja jest utrzymana przez jedno odliczenie, potem następuje powrót.\n\n### Kryteria oceny do aplikacji\n\n| Pole | Wynik | Kryterium z podręcznika |\n|---|---|---|\n| Zakres zgięcia | Pass | Może zgiąć szyję tak, aby broda znalazła się w odległości nie większej niż dwa palce od mostka. |\n| Zakres zgięcia | Fail | Nie może zgiąć szyi do odległości dwóch palców od mostka. |\n| Ból przy zgięciu | Positive / Ból | Ból jest obecny. |\n| Ból przy zgięciu | Negative / Brak bólu | Bólu nie ma. |\n\n### Dane do zapisu\n\nZapisz dwa pola bez strony: cervical_flexion_range oraz\ncervical_flexion_pain.\n\n## 2. Cervical Rotation and Extension\n\n**Kod:** cervical_rotation_extension  \n**Źródło:** Manual, strony 10-11.\n\n### Tekst do raportu\n\nTest ocenia zakres obrotu szyi w lewo i w prawo oraz obecność bólu podczas\nsamej rotacji i podczas rotacji połączonej z wyprostem.\n\n### Pozycja i wykonanie\n\n- Osoba stoi prosto, ze stopami razem, rękami wzdłuż tułowia i zamkniętymi\n  ustami.\n- Powoli obraca głowę w jedną stronę maksymalnie, lecz pod kontrolą.\n- Utrzymuje końcową pozycję przez jedno odliczenie.\n- Bez powrotu do pozycji neutralnej opuszcza ucho w kierunku barku po tej\n  samej stronie.\n- Wraca do pozycji wyjściowej i powtarza sekwencję po drugiej stronie.\n\n### Kryteria oceny do aplikacji\n\n| Pole | Wynik | Kryterium z podręcznika |\n|---|---|---|\n| Zakres rotacji, lewa/prawa | Pass | Broda dochodzi co najmniej do połowy obojczyka po ocenianej stronie. |\n| Zakres rotacji, lewa/prawa | Fail | Broda nie dochodzi do połowy obojczyka po ocenianej stronie. |\n| Ból przy rotacji, lewa/prawa | Positive / Ból | Ból jest obecny podczas rotacji. |\n| Ból przy rotacji, lewa/prawa | Negative / Brak bólu | Bólu nie ma podczas rotacji. |\n| Ból przy rotacji z wyprostem, lewa/prawa | Positive / Ból | Ból jest obecny podczas ruchu połączonego. |\n| Ból przy rotacji z wyprostem, lewa/prawa | Negative / Brak bólu | Bólu nie ma podczas ruchu połączonego. |\n\n### Definicja strony\n\nLewa strona oznacza rotację głowy w lewo i opuszczenie lewego ucha w kierunku\nlewego barku. Prawa strona oznacza ruch w prawo.\n\n### Dane do zapisu\n\nNa każdą stronę zapisz trzy niezależne pola: zakres rotacji, ból przy rotacji\ni ból przy rotacji z wyprostem.\n\n## 3. Toe Touch\n\n**Kod:** toe_touch  \n**Źródło:** Manual, strony 12-14.\n\n### Tekst do raportu\n\nTest jest oceną wzorca zgięcia w płaszczyźnie strzałkowej. Sprawdza, jak ciało\nkoordynuje mobilność i stabilność podczas skłonu do przodu.\n\n### Pozycja i wykonanie\n\n- Osoba rozpoczyna w staniu prostym, ze stopami razem i rękami wzdłuż tułowia.\n- Jedna stopa robi krok do przodu tak, aby wewnętrzna część pięty nogi z przodu\n  była ustawiona na wysokości końca dużego palca stopy przeciwnej.\n- Dłonie są jedna na drugiej przed ciałem.\n- Kolana pozostają proste, ale nie są blokowane.\n- Osoba pochyla się do przodu, próbując dotknąć palców stopy z tyłu.\n- Jeżeli po trzech próbach nie dotknie palców stopy z tyłu, próbuje dotknąć\n  palców stopy z przodu.\n- Następnie zmienia ustawienie nóg i powtarza test.\n\n### Definicja strony\n\nTest jest nazwany od nogi znajdującej się z tyłu, nie od nogi znajdującej się\nz przodu.\n\n### Kryteria oceny do aplikacji\n\n| Wynik | Kryterium z podręcznika |\n|---|---|\n| 3 | Dotknięcie palców stopy z tyłu bez zmiany wyjściowego ustawienia kolana. |\n| 2 | Brak dotknięcia palców stopy z tyłu, ale dotknięcie palców stopy z przodu; bez zmiany wyjściowego ustawienia kolana. |\n| 1 | Brak dotknięcia palców stopy z tyłu i z przodu albo zmiana wyjściowego ustawienia kolana. |\n| 0 | Ból w dowolnej części testu. |\n\n### Dane do zapisu\n\nZapisz wynik 0-3 osobno dla lewej i prawej nogi z tyłu. Wynik końcowy to\nniższy wynik L/R.\n\n## 4. Shoulder Mobility\n\n**Kod:** shoulder_mobility  \n**Źródło:** Manual, strony 15-16.\n\n### Tekst do raportu\n\nTest ocenia ruchomość górnej części ciała, kontrolę postawy, koordynację oraz\nróżnice między stronami podczas wzajemnego ruchu obu barków.\n\n### Pozycja i wykonanie\n\n- Najpierw mierzy się długość dominującej dłoni: od najbliższego nadgarstka\n  do końca palca środkowego.\n- Osoba stoi prosto, ze stopami razem i rękami wzdłuż tułowia.\n- Obie dłonie są zaciśnięte w pięści, palce obejmują kciuki.\n- Jedna pięść w jednym ruchu idzie nad głową i w dół pleców, a druga od dołu\n  pleców w górę.\n- Po ułożeniu rąk nie wolno przesuwać ich bliżej siebie.\n- Test powtarza się po drugiej stronie.\n\n### Definicja strony\n\nTest jest nazwany od ręki, która przechodzi nad głową.\n\n### Kryteria oceny do aplikacji\n\n| Wynik | Kryterium z podręcznika |\n|---|---|\n| 3 | Pięści znajdują się w odległości nie większej niż jedna długość dłoni. |\n| 2 | Pięści znajdują się w odległości nie większej niż półtorej długości dłoni. |\n| 1 | Pięści nie znajdują się w odległości półtorej długości dłoni. |\n| 0 | Ból w dowolnej części testu. |\n\n### Dane do zapisu\n\nZapisz wynik 0-3 osobno dla strony lewej i prawej. Wynik końcowy to niższy\nwynik L/R, chyba że Shoulder Clearing powoduje wynik 0.\n\n## 5. Shoulder Clearing - wzorzec górny i dolny\n\n**Kod:** shoulder_clearing  \n**Źródło:** Manual, strona 17.\n\n### Tekst do raportu\n\nTest clearing barku sprawdza, czy ból występuje podczas pozycji ręki nad głową\noraz podczas pozycji ręki za plecami.\n\n### Pozycja i wykonanie\n\nDla jednej strony:\n\n1. Osoba stoi prosto.\n2. Ręka przechodzi nad głową, łokieć się zgina, a dłoń dotyka górnej części\n   przeciwnej łopatki.\n3. Osoba wraca do pozycji wyjściowej.\n4. Ta sama ręka przechodzi za plecy i w górę, próbując dotknąć dolnej części\n   przeciwnej łopatki.\n5. Oba ruchy są powtarzane drugą ręką.\n\n### Pola do aplikacji\n\nNie zapisuj jednego wspólnego pola Shoulder Clearing. Zapisz cztery pola:\n\n| Strona | Wzorzec | Pole techniczne | Odpowiedzi |\n|---|---|---|---|\n| Lewa | Górny: lewa ręka do górnej części prawej łopatki | shoulder_clearing_upper_pain / left | Brak bólu / Ból |\n| Lewa | Dolny: lewa ręka za plecami do dolnej części prawej łopatki | shoulder_clearing_lower_pain / left | Brak bólu / Ból |\n| Prawa | Górny: prawa ręka do górnej części lewej łopatki | shoulder_clearing_upper_pain / right | Brak bólu / Ból |\n| Prawa | Dolny: prawa ręka za plecami do dolnej części lewej łopatki | shoulder_clearing_lower_pain / right | Brak bólu / Ból |\n\n### Reguła wyniku\n\n- Jeżeli w którymkolwiek z czterech pól wystąpi Ból / Positive, zbiorczy\n  Shoulder Clearing jest Positive.\n- Każdy Positive w którymkolwiek polu ustawia końcowy wynik całego Shoulder\n  Mobility na 0.\n- Raport ma wskazać stronę i wzorzec, który był Positive.\n- Zbiorczy Shoulder Clearing jest Negative tylko wtedy, gdy wszystkie cztery\n  pola są Negative.\n\nPodręcznik mówi, że przy bólu w clearing test zapisuje się Positive, a wynik\ncałego Shoulder Mobility wynosi 0.\n\n## 6. Rotation\n\n**Kod:** rotation  \n**Źródło:** Manual, strony 18-20.\n\n### Tekst do raportu\n\nTest ocenia rotację całego ciała i różnice między stronami.\n\n### Pozycja i wykonanie\n\n- Osoba stoi prosto, ze stopami razem i rękami wzdłuż tułowia.\n- Jedna noga robi krok do przodu tak, aby wewnętrzna część jej pięty była na\n  wysokości końca dużego palca drugiej stopy.\n- Ręce są wyprostowane przed klatką piersiową, palce splecione, kciuki\n  skierowane w górę, dłonie ustawione na wysokości nosa.\n- Bez zmiany ustawienia stóp osoba obraca ciało w stronę nogi z przodu.\n- Jeżeli po trzech próbach nie przekroczy 90 stopni w pozycji wykrocznej,\n  powtarza ruch ze stopami razem.\n\n### Definicja strony\n\nTest jest nazwany od kierunku, w którym obraca się ciało.\n\n### Kryteria oceny do aplikacji\n\n| Wynik | Kryterium z podręcznika |\n|---|---|\n| 3 | Obrót powyżej 90 stopni w pozycji wykrocznej bez zmiany ustawienia stóp. |\n| 2 | Obrót powyżej 90 stopni w pozycji symetrycznej, ale nie w wykrocznej; bez zmiany ustawienia stóp. |\n| 1 | Brak obrotu powyżej 90 stopni w pozycji symetrycznej albo zmiana ustawienia stóp. |\n| 0 | Ból w dowolnej części testu. |\n\n### Dane do zapisu\n\nZapisz wynik 0-3 dla lewego i prawego kierunku rotacji. Wynik końcowy to\nniższy wynik L/R.\n\n## 7. Balance\n\n**Kod:** balance  \n**Źródło:** Manual, strony 21-22.\n\n### Tekst do raportu\n\nTest ocenia stabilność na jednej nodze w różnych warunkach czuciowych.\n\n### Pozycja i wykonanie\n\n- Osoba stoi prosto, ze stopami razem i rękami wzdłuż tułowia.\n- Unosi jedno kolano i udo do wysokości zbliżonej do talii.\n- Utrzymuje stanie na jednej nodze z otwartymi oczami.\n- Jeżeli utrzyma pozycję przez 10 sekund z otwartymi oczami, zamyka oczy bez\n  zmiany pozycji i ponownie próbuje utrzymać pozycję.\n\n### Definicja strony\n\nTest jest nazwany od nogi, na której osoba stoi.\n\n### Kryteria oceny do aplikacji\n\n| Wynik | Kryterium z podręcznika |\n|---|---|\n| 3 | Utrzymanie równowagi przez 10 sekund z otwartymi i zamkniętymi oczami, bez istotnego kołysania i bez istotnego ruchu biodra/uda. |\n| 2 | Brak utrzymania 10 sekund z zamkniętymi oczami, ale utrzymanie 10 sekund z otwartymi oczami, bez istotnego kołysania i bez istotnego ruchu biodra/uda przy otwartych oczach. |\n| 1 | Brak utrzymania równowagi przez 10 sekund z otwartymi oczami albo istotne kołysanie i/lub ruch biodra/uda. |\n| 0 | Ból w dowolnej części testu. |\n\n### Dane do zapisu\n\nZapisz wynik 0-3 dla nogi lewej i prawej jako nogi podporowej. Wynik końcowy\nto niższy wynik L/R.\n\n## 8. Squat\n\n**Kod:** squat  \n**Źródło:** Manual, strony 23-25.\n\n### Tekst do raportu\n\nTest ocenia ruchomość i stabilność dolnej części ciała oraz gotowość do\nwykonania przysiadu w codziennym ruchu.\n\n### Pozycja i wykonanie\n\n- Osoba stoi ze stopami razem.\n- Ręce są wyprostowane przed klatką piersiową, najpierw dłonie są w pięściach.\n- Osoba schodzi w dół tak daleko, jak potrafi, utrzymując pięty na podłożu i\n  klatkę piersiową wysoko.\n- W dole przysiadu opuszcza pięści przy stopach, próbując dotknąć podłoża.\n- Jeżeli nie dotknie podłoża pięściami, powtarza przysiad z kciukami do góry i\n  palcami wyprostowanymi, próbując dotknąć podłoża palcami.\n\n### Kryteria oceny do aplikacji\n\n| Wynik | Kryterium z podręcznika |\n|---|---|\n| 3 | Dotknięcie podłoża pięściami obok stóp oraz udo poniżej poziomu. |\n| 2 | Brak dotknięcia podłoża pięścią i/lub brak uda poniżej poziomu, ale dotknięcie podłoża palcami obok stóp z udem poniżej poziomu. |\n| 1 | Brak dotknięcia podłoża palcami i/lub brak uda poniżej poziomu. |\n| 0 | Ból w dowolnej części testu. |\n\n### Dane do zapisu\n\nZapisz pojedynczy wynik 0-3. Test nie ma stron.\n\n## 9. Spine Extension Clearing\n\n**Kod:** spine_extension_clearing  \n**Źródło:** Manual, strona 26.\n\n### Tekst do raportu\n\nTest sprawdza, czy wyprost kręgosłupa może być wykonany komfortowo i bez bólu.\n\n### Pozycja i wykonanie\n\n- Osoba leży przodem na podłodze.\n- Dłonie są bezpośrednio pod barkami, płasko na podłożu.\n- Dolna część ciała pozostaje rozluźniona.\n- Osoba wypycha górną część ciała do góry do pełnego wyprostu łokci, a potem\n  wraca do pozycji wyjściowej.\n\n### Kryteria oceny do aplikacji\n\n| Wynik | Kryterium z podręcznika |\n|---|---|\n| Positive / Ból | Ból jest wywołany podczas testu. |\n| Negative / Brak bólu | Ból nie jest wywołany podczas testu. |\n\n### Dane do zapisu i reguły\n\nZapisz pojedyncze pole bez strony. Test nie ma własnej punktacji 0-3.\nW aktualnej konfiguracji Quick Screen jest widoczny jako flaga bólu i nie\nzmienia automatycznie wyniku Squat. Powiązanie z innym testem można dodać\nwyłącznie jako osobną regułę danego protokołu.\n\n## Układ w raporcie\n\n### Strona 1\n\n- Dane klienta i data.\n- Total Screen Score.\n- Wyniki aktualnego badania.\n- Wynik surowy, wynik końcowy i przyczyna zmiany wyniku.\n- Wykres historii i macierz historii.\n\n### Strona 2: Co obejmowało badanie i kryteria\n\nDla każdego testu pokaż:\n\n1. Tekst do raportu z sekcji danego testu.\n2. Definicję strony, jeżeli test jest obustronny.\n3. Tabelę kryteriów wyniku 0-3 albo Pass / Fail albo Ból / Brak bólu.\n4. Źródło w formie: FMS Quick Screen Manual, strona X.\n\nNie dodawaj na podstawie tych kryteriów automatycznej diagnozy ani wniosku.\n";
var FmsManual = (function () {
  var headings = { cervical_flexion: 1, cervical_rotation_extension: 2, toe_touch: 3, shoulder_mobility: 4, shoulder_clearing: 5, rotation: 6, balance: 7, squat: 8, spine_extension_clearing: 9 };
  function section(code) {
    var number = headings[code]; if (!number) return "";
    var match = FMS_MANUAL_SOURCE.match(new RegExp("^## " + number + "\\. [^\\n]+\\n([\\s\\S]*?)(?=^## \\d+\\. |$)", "m"));
    return match ? match[1].trim() : "";
  }
  function all() { var result = {}; Object.keys(headings).forEach(function (code) { result[code] = section(code); }); return result; }
  function common() { var marker = FMS_MANUAL_SOURCE.indexOf('## 1. '); return marker < 0 ? FMS_MANUAL_SOURCE : FMS_MANUAL_SOURCE.slice(0, marker).trim(); }
  return { section: section, all: all, common: common };
})();
